mapper.select:
SELECT * FROM ( SELECT SPECIAL.FINPROD_MARKET_ID finprodMarketId, SPECIAL.IS_ABS isAbs, SPECIAL.IS_SPECIAL_DEBT isSpecialDebt, SPECIAL.IS_DEFAULT_BOND_INDICATOR isDefaultBondIndicator, SPECIAL.INPUT_TYPE inputType, PRODUCT.FINPROD_ABBR finprodAbbr FROM FIN_PRODUCT_SPECIAL SPECIAL INNER JOIN FIN_PRODUCT PRODUCT ON SPECIAL.FINPROD_MARKET_ID = PRODUCT.FINPROD_MARKET_ID UNION SELECT SPECIAL.FINPROD_MARKET_ID finprodMarketId, SPECIAL.IS_ABS isAbs, SPECIAL.IS_SPECIAL_DEBT isSpecialDebt, SPECIAL.IS_DEFAULT_BOND_INDICATOR isDefaultBondIndicator, SPECIAL.INPUT_TYPE inputType, INTERF.SECNAME finprodAbbr FROM FIN_PRODUCT_SPECIAL SPECIAL INNER JOIN INTERF_PAYHSRCSECINFO INTERF ON SPECIAL.FINPROD_MARKET_ID = INTERF.SECID WHERE INTERF.SECID NOT IN (SELECT FINPROD_MARKET_ID FROM FIN_PRODUCT WHERE FINPROD_TYPE2 = 'F01' AND TRADE_MARKET = '01') )
AND ( FINPRODMARKETID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR FINPRODABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) )
and FINPRODMARKETID = #{finprodMarketId}
and ISABS = #{isAbs}
and ISSPECIALDEBT = #{isSpecialDebt}
and ISDEFAULTBONDINDICATOR = #{isDefaultBondIndicator}
order by ${pageMode.sort} ${pageMode.direction}
ORDER BY FINPRODMARKETID, ISSPECIALDEBT, ISDEFAULTBONDINDICATOR, ISABS

select sum(qty) qty
from (
         select count(1) as qty
         from ETR_ENTRUST
         where FINPROD_ID = #{finprodId}
           AND ENTRUST_DATE = to_date(#{iPlatformDate}, 'yyyy-MM-dd')
         union all
         select count(1) as qty
         from WFL_ETR_ENTRUST
         where FINPROD_ID = #{finprodId}
           AND ENTRUST_DATE = to_date(#{iPlatformDate}, 'yyyy-MM-dd')
     )

select sum(qty) qty
from (
         select count(1) as qty
         from ETR_ENTRUST
         where FINPROD_ID = #{finprodId}
         union all
         select count(1) as qty
         from WFL_ETR_ENTRUST
         where FINPROD_ID = #{finprodId}
     )

SELECT SECID id, SECNAME text
from INTERF_PAYHSRCSECINFO
WHERE SECNAME = #{search}

SELECT FINPROD_ID id, FINPROD_ABBR text
from FIN_PRODUCT
where FINPROD_ABBR = #{search}
